const deviceStore = global.get("deviceStore");
const timeHelpers = global.get("timeHelpers");
if (!deviceStore || typeof deviceStore.ensureRuntime !== "function") {
    node.error("deviceStore.ensureRuntime missing");
    return null;
}
if (!timeHelpers || typeof timeHelpers.nowIso !== "function") {
    node.error("timeHelpers.nowIso missing");
    return null;
}
const now = timeHelpers.nowIso();
const existing = global.get("smarthome_runtime");
const runtime = deviceStore.ensureRuntime(existing, now);
global.set("smarthome_runtime", runtime);
msg.payload = {
    status: "bootstrapped",
    initialized_at: runtime.initialized_at,
    device_count: Object.keys(runtime.devices || {}).length,
    master_count: Object.keys(runtime.masters || {}).length
};
return msg;
